diff --git a/crates/callisto-cli/tests/release_pr_pre_cycle_tests.rs b/crates/callisto-cli/tests/release_pr_pre_cycle_tests.rs
new file mode 100644
index 000000000..a58a75463
--- /dev/null
+++ b/crates/callisto-cli/tests/release_pr_pre_cycle_tests.rs
@@ -0,0 +1,136 @@
+#![cfg(unix)]
+
+//! A whole prerelease cycle through the release pull request: each `release-pr decide` opens a PR only when the
+//! cycle has something new, and each merged version commit verifies as release authority.
+
+#[path = "common/release_harness.rs"]
+mod release_harness;
+
+use std::fs;
+use std::path::Path;
+
+use release_harness::*;
+
+fn decide(root: &Path) -> String {
+    let snapshot = callisto_model::ReleasePrSnapshotV2::new(
+        callisto_model::GitHubRepository::parse("example/core-crate").unwrap(),
+        "main".into(),
+        callisto_model::CommitSha::parse(&"a".repeat(40)).unwrap(),
+        vec![],
+    )
+    .unwrap();
+    let out = callisto(
+        root,
+        &[
+            "release-pr",
+            "decide",
+            "--snapshot",
+            &serde_json::to_string(&snapshot).unwrap(),
+            "--repository",
+            "example/core-crate",
+            "--base-branch",
+            "main",
+            "--release-branch",
+            "callisto/version-packages",
+        ],
+    );
+    assert!(out.status.success(), "{}", String::from_utf8_lossy(&out.stderr));
+    let report: serde_json::Value = serde_json::from_slice(&out.stdout).unwrap();
+    report["action"]["kind"].as_str().unwrap().to_string()
+}
+
+/// Opens, merges and verifies one release PR; returns the version it released.
+fn release(root: &Path) -> String {
+    assert_eq!(decide(root), "create");
+    let version = callisto(
+        root,
+        &["version", "--no-refresh-lockfiles", "--emit-decision", DECISION_PATH],
+    );
+    assert!(version.status.success(), "{}", String::from_utf8_lossy(&version.stderr));
+    git(root, &["add", "-A"]);
+    git(root, &["commit", "-q", "-m", "chore(release): version packages"]);
+    let commit = git(root, &["rev-parse", "HEAD"]);
+    git(root, &["checkout", "-q", "--detach", &commit]);
+    let external = tempfile::tempdir().unwrap();
+    let plan = callisto(
+        root,
+        &[
+            "release",
+            "plan",
+            "--from-release-commit",
+            &commit,
+            "--decision",
+            DECISION_PATH,
+            "--out",
+            external.path().join("intent.json").to_str().unwrap(),
+        ],
+    );
+    assert!(plan.status.success(), "{}", String::from_utf8_lossy(&plan.stderr));
+    git(root, &["checkout", "-q", "main"]);
+    git(root, &["merge", "-q", "--ff-only", &commit]);
+    let decision: serde_json::Value =
+        serde_json::from_str(&fs::read_to_string(root.join(DECISION_PATH)).unwrap()).unwrap();
+    decision["entries"][0]["targetVersion"].as_str().unwrap().to_string()
+}
+
+fn add(root: &Path, bump: &str, summary: &str) {
+    let out = callisto(
+        root,
+        &[
+            "add",
+            "--package",
+            &format!("cargo/core-crate:{bump}"),
+            "--summary",
+            summary,
+        ],
+    );
+    assert!(out.status.success(), "{}", String::from_utf8_lossy(&out.stderr));
+    git(root, &["add", "-A"]);
+    git(root, &["commit", "-q", "-m", summary]);
+}
+
+#[test]
+fn a_prerelease_cycle_runs_end_to_end_through_release_pull_requests() {
+    let dir = tempfile::tempdir().unwrap();
+    let root = dir.path();
+    callisto_fixtures::git::init_repo(root);
+    git(
+        root,
+        &["remote", "add", "origin", "https://github.com/example/core-crate.git"],
+    );
+    fs::write(
+        root.join("Cargo.toml"),
+        "[package]\nname = \"core-crate\"\nversion = \"1.0.0\"\nedition = \"2021\"\ndescription = \"t\"\nlicense = \"MIT\"\n",
+    )
+    .unwrap();
+    fs::create_dir_all(root.join("src")).unwrap();
+    fs::write(root.join("src/lib.rs"), "pub fn core() {}\n").unwrap();
+    fs::write(
+        root.join("callisto.toml"),
+        "[[package]]\nmatch = \"cargo/core-crate\"\npublish-to = [\"crates-io\"]\n",
+    )
+    .unwrap();
+    git(root, &["add", "-A"]);
+    git(root, &["commit", "-q", "-m", "initial"]);
+
+    let enter = callisto(root, &["pre", "enter", "beta"]);
+    assert!(enter.status.success(), "{}", String::from_utf8_lossy(&enter.stderr));
+    git(root, &["commit", "-q", "-am", "enter beta"]);
+    assert_eq!(decide(root), "noop", "entering a cycle releases nothing on its own");
+
+    add(root, "minor", "Add a feature");
+    assert_eq!(release(root), "1.1.0-beta.0");
+
+    add(root, "patch", "Fix the feature");
+    assert_eq!(release(root), "1.1.0-beta.1");
+
+    assert_eq!(decide(root), "noop", "a cycle with nothing new opens no pull request");
+
+    let exit = callisto(root, &["pre", "exit"]);
+    assert!(exit.status.success(), "{}", String::from_utf8_lossy(&exit.stderr));
+    git(root, &["commit", "-q", "-am", "exit beta"]);
+    assert_eq!(release(root), "1.1.0");
+    assert!(!root.join(".changeset/pre.json").exists());
+
+    assert_eq!(decide(root), "noop");
+}
diff --git a/docs/releasing.md b/docs/releasing.md
index 84308d1b4..f75208b9d 100644
--- a/docs/releasing.md
+++ b/docs/releasing.md
@@ -116,7 +116,9 @@ Recover each one with the dispatch below, oldest first.

 Callisto's workflow rebuilds the release PR on every push to `main`. While that rebuild is pending the PR is stale: if changesets changed on `main` since it was built, merging it releases the wrong set. So a second workflow, `Hold release PR`, turns the open release PR into a draft the moment `main` moves, and the release workflow marks it ready only after a rebuild from the new tip. If the rebuild fails, the PR stays a draft and cannot be merged. Re-run that `Release` workflow run, and the PR becomes ready when it succeeds. A transient GitHub error during the rebuild is attempted up to four times in all before it fails.

-If a stale release PR whose changesets were already consumed on `main` was merged anyway, the release fails with [E165](errors.md) because the changesets the merge deleted are not the ones its decision recorded, and every later push to `main` retries it. A stale PR that releases only bumps inferred from commits deletes no changesets, so E165 does not catch it: keep `Hold release PR` enabled, which keeps a stale PR in draft. Nothing was published. Revert the merge's release payload (the version bumps, changelog entries and `.callisto/release-decision.json`, not the changeset files) in a pull request to `main`. The next push rebuilds the release PR from the changesets that are really pending.
+If a stale release PR whose changesets were already consumed on `main` was merged anyway, the release fails with [E165](errors.md) because the changesets the merge deleted are not the ones its decision recorded, and every later push to `main` retries it. A stale PR that deletes no changesets, one that releases only bumps inferred from commits or a prerelease PR of a Changesets v2 pre cycle, is not caught that way: E165 still refuses it when `main` already holds its versions, and `Hold release PR` keeps a stale PR in draft.
+
+During a pre cycle (`callisto pre enter <tag>`) the release PR works the same way: each new changeset or inferred commit opens a PR for the next prerelease, a cycle with nothing new opens none, and after `callisto pre exit` the next PR releases the stable versions. Nothing was published. Revert the merge's release payload (the version bumps, changelog entries and `.callisto/release-decision.json`, not the changeset files) in a pull request to `main`. The next push rebuilds the release PR from the changesets that are really pending.

 ## Recovering an older release

